# fix transform based on bar intervals

def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 top=[c for c,v in enumerate(grid[0]) if v==2]; bot=[c for c,v in enumerate(grid[-1]) if v==2]
 # infer offset by bar starts
 delta=bot[0]-top[0]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=6: continue
   if c in top:
    # ray from top edge to marker, plus corresponding full vertical bridge at bottom position
    for i in range(1,r):
     if out[i][c]==5: out[i][c]=6
    out[r][c]=4
    cc=c+delta
    if 0<=cc<w:
     for i in range(1,h-1):
      if out[i][cc]==5: out[i][cc]=6
   elif c in bot:
    for i in range(r+1,h-1):
     if out[i][c]==5: out[i][c]=6
    out[r][c]=4
    cc=c-delta
    if 0<=cc<w:
     for i in range(1,h-1):
      if out[i][cc]==5: out[i][cc]=6
 return out
